:false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s13c17_auth_flow_b2b":false,"s13c17_resultado_servidor":false,"s13c17_transicion_o_estado_invalido":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s13c17_auth_flow_b2b":false,"s13c17_resultado_servidor":true,"s13c17_transicion_o_estado_invalido":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s13c17_auth_flow_b2b":false,"s13c17_resultado_servidor":true,"s13c17_transicion_o_estado_invalido":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s13c17_auth_flow_b2b":true,"s13c17_resultado_servidor":false,"s13c17_transicion_o_estado_invalido":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s13c17_auth_flow_b2b":true,"s13c17_resultado_servidor":false,"s13c17_transicion_o_estado_invalido":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s13c17_auth_flow_b2b":true,"s13c17_resultado_servidor":true,"s13c17_transicion_o_estado_invalido":false},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"s13c17_auth_flow_b2b":true,"s13c17_resultado_servidor":true,"s13c17_transicion_o_estado_invalido":true},"esperado":true}],"efecto":"BLOQUEAR","autoridad":"LEG-TECNICO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/655","solicitante":"Cristhian / Claude S13 2026-11-24"}}]$packets$::jsonb) LOOP
 cd:=p->>'codigo'; lid:=substring(p->'origen'->>'ref' from '[0-9]+$')::int;
 IF (SELECT count(*) FROM lf_ops.reglas)=586 AND NOT EXISTS(SELECT 1 FROM lf_ops.reglas WHERE id=lid AND estado='VIGENTE' AND NOT coalesce(pendiente_decision,false)) THEN RAISE EXCEPTION 'S13_SOURCE_NOT_ELIGIBLE %',lid; END IF;
 IF EXISTS(SELECT 1 FROM lf_ops.lf_nucleo_cobertura_legada WHERE legacy_id=lid AND estado_cobertura='REEMPLAZADA') THEN RAISE EXCEPTION 'S13_ALREADY_COVERED %',lid; END IF;
 q:=lf_ops.nucleo_regla_proponer_v1(p,false);
 IF q->>'resultado'<>'EVALUADA_SIN_ESCRIBIR' OR (q->>'bloqueantes')::int<>0 THEN RAISE EXCEPTION 'S13_PREFLIGHT_FAIL % %',cd,q; END IF;
 q:=lf_ops.nucleo_regla_proponer_v1(p,true);
 IF q->>'resultado'<>'CANDIDATA' OR (q->>'version')::int<>1 THEN RAISE EXCEPTION 'S13_CREATE_FAIL % %',cd,q; END IF;
 IF (SELECT count(*) FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1)<>8 OR (SELECT count(distinct entrada::text) FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1)<>8 THEN RAISE EXCEPTION 'S13_VECTOR_INVALID %',cd; END IF;
 e:=lf_ops.nucleo_regla_evaluar_v1(cd,true);
 IF e->>'decision'<>'BLOQUEADA' OR e->>'hash_paquete' IS NULL THEN RAISE EXCEPTION 'S13_GATE_FAIL % %',cd,e; END IF;
 n:=n+1; RAISE NOTICE 'S13_CANDIDATE % hash=%',cd,e->>'hash_paquete';
 END LOOP;
 IF n<>17 OR (SELECT count(*) FROM lf_ops.nucleo_regla_versiones WHERE estado='CANDIDATA')<>b_cand+17 OR (SELECT count(*) FROM lf_ops.nucleo_regla_pruebas WHERE regla LIKE 'S13-C%')<>136
 OR (SELECT jsonb_agg(to_jsonb(t) ORDER BY id) FROM lf_ops.reglas t) IS DISTINCT FROM b_leg
 OR (SELECT jsonb_agg(to_jsonb(t) ORDER BY legacy_id,nucleo_codigo,version_nucleo) FROM lf_ops.lf_nucleo_cobertura_legada t) IS DISTINCT FROM b_bridge
 OR (SELECT jsonb_agg(to_jsonb(t) ORDER BY regla,version) FROM lf_ops.nucleo_regla_versiones t WHERE estado='PUBLICADA') IS DISTINCT FROM b_pub
 OR (SELECT jsonb_agg(to_jsonb(t) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones t) IS DISTINCT FROM b_dep
 OR (SELECT jsonb_agg(to_jsonb(t) ORDER BY id) FROM lf_ops.nucleo_juicios t) IS DISTINCT FROM b_judge THEN RAISE EXCEPTION 'S13_CONSERVATION_FAIL'; END IF;
 IF EXISTS(SELECT 1 FROM lf_ops.pantallas WHERE id=36) AND jsonb_array_length(lf_ops.lf_nucleo_lectura_transicion_v1(36,'INPUT_GOVERNANCE','DIRECTAS')->'nativas') IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'S13_DPIG03_FAIL'; END IF;
 RAISE NOTICE 'S13_PASS 17 CANDIDATAS 136 VECTORES 0 PROMOCIONES';
END $s13$;
COMMIT;
